window.IMGUI_DOCS.guides.push(...[{"id":"engine-editor-architecture","category":"engine","level":"intermediate","minutes":18,"title":"自作エンジンの最初の一歩：UIとゲームの仕事を分けよう","summary":"Hierarchy、Inspector、Sceneビュー。まずは3枚のパネルが同じデータを見られる、小さなエディターから始めてみましょう。","related_api":["ImGui::Begin","ImGui::End","ImGui::Selectable","ImGui::DragFloat3","ImGui::Button"],"related_guides":["frame-state","frame-integration","engine-hierarchy-ids","engine-undo-redo"],"tags":["ゲームエンジン","エディター設計","状態管理"],"sections":[{"title":"ImGuiが担当するのは、エンジンを操作する画面","paragraphs":["Dear ImGuiが用意してくれるのは、ボタンや入力欄を並べて操作するための仕組みです。**3D描画、ECS、物理、アセット管理はアプリ側で用意します。** UIだけでエンジンの処理まで揃うわけではありません。","難しく考えすぎず、まず「選択中の物体を変える」「位置を編集する」「変更を保存候補にする」の3つをつなぎましょう。パネルごとに別の位置データを持つと、Inspectorを動かしてもSceneに反映されない、というすれ違いが起きます。"],"table":{"headers":["役割","持っておくデータ","担当する処理"],"rows":[["エンジンモデル","物体・Transform・アセットID","シミュレーション・描画・保存"],["エディター状態","選択ID・開いているパネル","選択・表示モード・履歴"],["ImGuiの呼び出し","モデルへの参照","入力欄と操作結果の受け渡し"]]},"id":"engine-editor-architecture-section-1"},{"title":"3つのパネルから、1つのモデルを触ってみる","paragraphs":["次の関数はNewFrame()とRender()の間で毎フレーム呼びます。モデルは呼び出し元が保持してください。ここでのdirtyは「未保存の変更がある」というアプリ側の印です。"],"code":"#include \"imgui.h\"\n    struct EditorModel\n    {\n        bool selected = true;\n        bool dirty = false;\n        float position[3] = {0.0f, 0.0f, 0.0f};\n    };\n    void DrawSmallEditor(EditorModel & model)\n    {\n        if (ImGui::Begin(\"Hierarchy\"))\n        {\n            if (ImGui::Selectable(\"Cube\", model.selected))\n                model.selected = !model.selected;\n        }\n        ImGui::End();\n        if (ImGui::Begin(\"Inspector\") && model.selected)\n        {\n            if (ImGui::DragFloat3(\"Position\", model.position, 0.05f))\n                model.dirty = true;\n        }\n        ImGui::End();\n        if (ImGui::Begin(\"Scene\"))\n        {\n            ImGui::Text(\"Cube: %.2f, %.2f, %.2f\",\n                model.position[0],\n                model.position[1],\n                model.position[2]);\n            ImGui::TextUnformatted(model.dirty ? \"Unsaved changes\" : \"Saved\");\n        }\n        ImGui::End();\n    }","id":"engine-editor-architecture-section-2","capture":{"guide_id":"engine-editor-architecture","section_index":1,"scene":"example-engine-editor-architecture-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"dd26c9148df7112e2ec9553c2c6a3411a8166a0fd440878371d7d1d53efaeedb","image_sha256":"27a65f7b427276d44e173895f6f9945050e3344a5c220e09a7aeeab298a8f1f6","fixture":"static EditorModel model; DrawSmallEditor(model);","initialization":""}},{"title":"変更すると困る処理は、いったん要求として集める","paragraphs":["名前の編集程度ならその場で値を書き換えても始められます。一方、物体の削除やシーン切り替えは、他のパネルが参照している途中に実行すると危険です。**UIでは要求を積み、全パネルを描き終えてから反映する**形にすると扱いやすくなります。","次はキューの最小モデルです。ボタンは削除要求を追加するだけで、実際の反映は呼び出し元がUI処理の後に行います。Undoを付けるときも、この変更の入口を活用できます。"],"code":"#include \"imgui.h\"\n#include <vector>\n    enum class EditKind\n    {\n        DeleteObject,\n        ResetPosition\n    };\n    struct EditRequest\n    {\n        EditKind kind;\n        int entity_id;\n    };\n    struct ObjectModel\n    {\n        int id = 1;\n        bool alive = true;\n        float x = 2.0f;\n    };\n    void DrawObjectActions(int selected_id, std::vector<EditRequest>& requests)\n    {\n        if (ImGui::Button(\"Delete\"))\n            requests.push_back({EditKind::DeleteObject, selected_id});\n        ImGui::SameLine();\n        if (ImGui::Button(\"Reset position\"))\n            requests.push_back({EditKind::ResetPosition, selected_id});\n    }\n    void ApplyRequests(\n        ObjectModel & object, std::vector<EditRequest> & requests)\n    {\n        for (const EditRequest& request : requests)\n        {\n            if (!object.alive || request.entity_id != object.id)\n                continue;\n            if (request.kind == EditKind::DeleteObject)\n                object.alive = false;\n            else\n                object.x = 0.0f;\n        }\n        requests.clear();\n    }","id":"engine-editor-architecture-section-3","capture":{"guide_id":"engine-editor-architecture","section_index":2,"scene":"example-engine-editor-architecture-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"3dace9c296bdde6c12db9eb46ddd4104b3002ad569a8f4119aa23503e1f4c119","image_sha256":"7c0afed8ba989cec7a3ae46b0d7757caa2a38d3fe70d1c1e4032b60d640bb5c7","fixture":"static ObjectModel model; static std::vector<EditRequest> requests; DrawObjectActions(1, requests); ApplyRequests(model, requests); ImGui::Text(\"Pending requests: %zu\", requests.size());","initialization":""}},{"title":"フレームの順番を決めておこう","paragraphs":["最初は「イベントを読む → ImGuiのNewFrame → パネルを作る → 編集要求を反映 → エンジン更新 → シーンとUIを描画」という流れを紙に書いておくと、値がいつ変わるか追いやすくなります。既存エンジンが別の更新順なら、どの時点の状態をUIに見せるかを明示しましょう。","Render()はImGuiの描画データをまとめる処理です。シーンの描画やGPUへの送信、Presentまで自動で行う処理ではありません。Sceneパネルに3D画像を出す段階では、アプリのレンダラーが作ったテクスチャをImage()へ渡します。"],"id":"engine-editor-architecture-section-4"},{"title":"小さく動いたら、次に何を足す？","paragraphs":["次は選択をboolから安定したEntity IDへ変えてみましょう。名前変更、並べ替え、削除をしても選択が別の物体へ飛ばないことを確かめると、エディターの土台がぐっと丈夫になります。"],"bullets":["最初から全コンポーネントを自動表示しようとせず、Transformひとつで編集の流れを完成させましょう。","UI内のstaticは試作に便利ですが、複数プロジェクトや複数シーンではエディター状態を明示的なオブジェクトにまとめると混ざりません。","レイアウトの自由な配置はDockingブランチへ進んでから追加できます。"],"id":"engine-editor-architecture-section-5"},{"title":"App・Editor・Rendererのつながり","paragraphs":["Appがシーンと設定を保持し、Editorが選択中の値を編集し、Rendererがその結果から画像を作ります。画像用テクスチャの寿命は、ImGuiが描画し終わるまで保ちましょう。実アプリでは画像を当フレーム/前フレームのどちらで見せるかも描画順と合わせて決めます。"],"flow":["App：シーン・選択ID・Undoを保持","Editor：NewFrameの後、保持データを読み書き","Renderer：3D画像をレンダーターゲットへ描く","UI描画：Imageで参照 → Render/GetDrawData → GPUへ提出"],"id":"engine-editor-architecture-section-6"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"自作エンジン作者の開発記録: エディターと実行系の構成","url":"https://hanion.dev/post/enik-engine/"}],"image":"guide-engine-workbench","image_scene":"example-engine-editor-architecture-02","image_caption":""},{"id":"engine-hierarchy-ids","category":"engine","level":"intermediate","minutes":20,"title":"Hierarchyを作ろう：名前が変わっても選択を保つID設計","summary":"同じ名前のCubeが並んでも大丈夫。表示名、物体のID、ImGuiのIDを分けて、選択が迷子にならない一覧を作ります。","related_api":["ImGui::PushID","ImGui::PopID","ImGui::TreeNodeEx","ImGui::TreePop","ImGui::IsItemClicked","ImGui::IsItemToggledOpen"],"related_guides":["id-stack","labels-hash","engine-safe-deletion","engine-transform-inspector","visual-marquee"],"tags":["Hierarchy","Entity ID","選択","ツリー"],"sections":[{"title":"名前や配列の位置を、物体の正体にしない","paragraphs":["名前は後から変わりますし、配列の添字は並べ替えると変わります。**選択状態には物体ごとに変わらないIDを保存する**のがおすすめです。ImGuiのIDはUI状態を識別するためのもので、保存ファイルのEntity IDを置き換えるものではありません。","以下は説明用に、0を未選択とする正のint IDを使います。実際のECSが64bit IDや世代付きハンドルなら、その体系を維持してください。PushID(int)へ64bit値を切り詰めると衝突の原因になるので、完全なIDを文字列へ変換するなどの方法を選びます。"],"id":"engine-hierarchy-ids-section-1"},{"title":"まずは安定IDを使った平らな一覧から","paragraphs":["この関数は有効なImGuiウィンドウ内で呼びます。PushIDで物体ごとの名前空間を作り、ラベルの###以降を固定すると、表示名が変わっても同じUI項目として扱えます。PushIDだけでなく、Selectable自身のラベルIDも固定するのがポイントです。"],"code":"#include \"imgui.h\"\n#include <string>\n#include <vector>\n    struct EntityRow\n    {\n        int id;\n        std::string name;\n    };\n    void DrawEntityList(\n        const std::vector<EntityRow>& entities, int& selected_id)\n    {\n        for (const EntityRow& entity : entities)\n        {\n            ImGui::PushID(entity.id);\n            const std::string label = entity.name + \"###entity\";\n            if (ImGui::Selectable(label.c_str(), selected_id == entity.id))\n                selected_id = entity.id;\n            ImGui::PopID();\n        }\n    }","id":"engine-hierarchy-ids-section-2","capture":{"guide_id":"engine-hierarchy-ids","section_index":1,"scene":"example-engine-hierarchy-ids-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"a9d25a7b28753566518e37ac78530be5bb8367219a0e75923a5d1c18aa5c1c15","image_sha256":"76d94c354c4486266114f35dc775405e6cf741b1da705bc5de7959ea6d5ffe34","fixture":"static std::vector<EntityRow> rows{{101,\"Camera\"},{205,\"Player\"},{310,\"Ground\"}}; static int selected = 205; DrawEntityList(rows, selected); ImGui::Text(\"Selected entity: %d\", selected);","initialization":""}},{"title":"親子ツリーでも、選択はIDで受け渡す","paragraphs":["TreeNodeEx()がtrueなら、そのノードが開いた状態です。下の例は葉にもNoTreePushOnOpenを付けず、trueのとき必ずTreePop()する書き方に揃えています。","循環のない親子構造を前提にしています。ドラッグで親を付け替える処理では、自分自身や自分の子孫を親にできないよう、エンジン側で検証が必要です。"],"code":"#include \"imgui.h\"\n#include <string>\n#include <vector>\n    struct TreeEntity\n    {\n        int id;\n        std::string name;\n        std::vector<TreeEntity> children;\n    };\n    void DrawHierarchyNode(const TreeEntity& entity, int& selected_id)\n    {\n        ImGui::PushID(entity.id);\n        ImGuiTreeNodeFlags flags =\n            ImGuiTreeNodeFlags_OpenOnArrow | ImGuiTreeNodeFlags_SpanAvailWidth;\n        if (selected_id == entity.id)\n            flags |= ImGuiTreeNodeFlags_Selected;\n        if (entity.children.empty())\n            flags |= ImGuiTreeNodeFlags_Leaf;\n        const bool open =\n            ImGui::TreeNodeEx(\"node\", flags, \"%s\", entity.name.c_str());\n        if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen())\n            selected_id = entity.id;\n        if (open)\n        {\n            for (const TreeEntity& child : entity.children)\n                DrawHierarchyNode(child, selected_id);\n            ImGui::TreePop();\n        }\n        ImGui::PopID();\n    }","id":"engine-hierarchy-ids-section-3","capture":{"guide_id":"engine-hierarchy-ids","section_index":2,"scene":"example-engine-hierarchy-ids-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"a6d081653f215bedc6c0a42226014d3abd998add0b8a563189b6a8308eb59469","image_sha256":"1fa278d39e82ed0ab6361ce00c3530e9a7bb2e177c271a4adbc90b7f4c501a00","fixture":"static TreeEntity root{1,\"World\",{{101,\"Camera\",{}},{205,\"Player\",{{206,\"Weapon\",{}}}},{310,\"Ground\",{}}}}; static int selected=205; ImGui::SetNextItemOpen(true, ImGuiCond_Always); DrawHierarchyNode(root,selected); ImGui::Text(\"Selected entity: %d\",selected);","initialization":""}},{"title":"親を移動すると、UIのパスも変わる","paragraphs":["上の再帰では祖先ノードもImGuiのIDスタックに入るため、親を付け替えるとその子のUI IDは変わります。**Entity IDによる選択は残っても、ツリーの開閉状態は別**です。親をまたぐ移動でも開閉を保ちたいなら、開閉状態もアプリ側のEntity IDで管理し、SetNextItemOpen()で反映する設計へ進めます。","物体のアドレスをPushIDへ渡す方法は、そのアドレスが変わらない間だけ安定します。vectorの再確保やコンポーネント移動があるエンジンでは、ポインターよりEntity IDを使う方が意図を説明しやすくなります。"],"id":"engine-hierarchy-ids-section-4"},{"title":"確認は「同じ名前を2つ置く」から","paragraphs":["Cubeを2個作り、片方を選択してから名前変更、並べ替え、親変更、削除を順に試しましょう。Inspectorが別のCubeを編集しないことと、削除後に未選択へ戻ることを確認します。"],"bullets":["表示名にはTextやTreeNodeExの書式引数として渡し、ユーザー入力をprintfの書式文字列にしないようにしましょう。","IDの再利用があるエンジンでは、番号だけでなく世代も含むハンドルを選択状態に持たせます。","大量ノードの描画を最適化する前に、安定IDと削除時の挙動を決めておくと後戻りが減ります。"],"id":"engine-hierarchy-ids-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-hierarchy-ids-02","image_caption":""},{"id":"engine-transform-inspector","category":"engine","level":"intermediate","minutes":18,"title":"Transform Inspectorを育てよう：単位と編集ルールも伝える","summary":"位置・回転・拡大率を並べるだけでなく、「いま何を、どの単位で変えているのか」が分かるInspectorにしてみましょう。","related_api":["ImGui::DragFloat3","ImGui::SeparatorText","ImGui::BeginTable","ImGui::TableNextRow","ImGui::TableSetColumnIndex","ImGui::BeginDisabled"],"related_guides":["number-input","engine-hierarchy-ids","engine-undo-redo"],"tags":["Inspector","Transform","単位","編集"],"sections":[{"title":"まずは値の意味をUIに出しておこう","paragraphs":["Transformにはローカル座標とワールド座標があり、回転も度数法とラジアンで混同しがちです。**ラベルや補足に座標系と単位を書く**だけで、「数値は変わったのに思った方向に動かない」を減らせます。","例のTransformはローカル位置、度単位のオイラー角、拡大率を持つ説明用モデルです。クォータニオンを使うエンジンでは、表示用の角度と内部データを変換する処理をアプリ側で用意します。単にクォータニオンの先頭3要素へDragFloat3をつなぐことはできません。"],"id":"engine-transform-inspector-section-1"},{"title":"3項目を、小さな部品としてまとめる","paragraphs":["戻り値は「どれかの値が今回変わったか」です。レンダラーへの通知やdirtyの更新は呼び出し元で行うと、UI部品がエンジンの詳細を抱えすぎずに済みます。"],"code":"#include \"imgui.h\"\n    struct LocalTransform\n    {\n        float position[3] = {0.0f, 0.0f, 0.0f};\n        float euler_degrees[3] = {0.0f, 0.0f, 0.0f};\n        float scale[3] = {1.0f, 1.0f, 1.0f};\n    };\n    bool DrawLocalTransform(LocalTransform & transform)\n    {\n        bool changed = false;\n        ImGui::SeparatorText(\"Local Transform\");\n        changed |= ImGui::DragFloat3(\"Position (m)\", transform.position, 0.01f);\n        changed |=\n            ImGui::DragFloat3(\"Rotation (deg)\", transform.euler_degrees, 0.5f);\n        changed |= ImGui::DragFloat3(\"Scale\",\n            transform.scale,\n            0.01f,\n            0.001f,\n            100.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        return changed;\n    }","id":"engine-transform-inspector-section-2","capture":{"guide_id":"engine-transform-inspector","section_index":1,"scene":"example-engine-transform-inspector-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"0b844acf316040067f092f0c0600d584d884a1a75f31e79b3557ebfba15f187e","image_sha256":"17f43859ce4d889ac88ed698be00de93406683360c00af6b02c29923298c625c","fixture":"static LocalTransform value; DrawLocalTransform(value);","initialization":""}},{"title":"項目が増えたら、ラベルと値を2列へ","paragraphs":["数値欄の端が揃うと、コンポーネントが増えても目で追いやすくなります。次は同じTransform型を前提にしない、1つのfloat3を編集する独立した部品です。呼び出しごとに固有のidを渡します。"],"code":"#include \"imgui.h\"\n    bool DrawVectorProperty(\n        const char* id, const char* label, float value[3], bool editable)\n    {\n        bool changed = false;\n        ImGui::PushID(id);\n        if (ImGui::BeginTable(\"property\", 2, ImGuiTableFlags_SizingStretchProp))\n        {\n            ImGui::TableSetupColumn(\n                \"Name\", ImGuiTableColumnFlags_WidthFixed, 130.0f);\n            ImGui::TableSetupColumn(\n                \"Value\", ImGuiTableColumnFlags_WidthStretch);\n            ImGui::TableNextRow();\n            ImGui::TableSetColumnIndex(0);\n            ImGui::AlignTextToFramePadding();\n            ImGui::TextUnformatted(label);\n            ImGui::TableSetColumnIndex(1);\n            ImGui::SetNextItemWidth(-1.0f);\n            ImGui::BeginDisabled(!editable);\n            changed = ImGui::DragFloat3(\"##value\", value, 0.01f);\n            ImGui::EndDisabled();\n            ImGui::EndTable();\n        }\n        ImGui::PopID();\n        return changed;\n    }","id":"engine-transform-inspector-section-3","capture":{"guide_id":"engine-transform-inspector","section_index":2,"scene":"example-engine-transform-inspector-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"4318251e299fe7163341f0a738a21813518e1e1c22ad3c5af842ae0500eee5f3","image_sha256":"2ad876031c85931fdb15a1fa242c050cd1985e704d086471f95dd2168128386b","fixture":"static float value[3]={1.25f,2.0f,-3.0f}; DrawVectorProperty(\"position\",\"Position (m)\",value,true);","initialization":""}},{"title":"入力範囲は、エンジンのルールと合わせよう","paragraphs":["最初の例では拡大率を正の範囲へ制限しています。これはこのモデルでの方針で、負の拡大率による反転が必要なエンジンなら別の制約にしてください。ゼロ拡大率を許すと逆行列を作れない場合があるので、描画・物理側の仕様とも相談します。","ImGuiSliderFlags_AlwaysClampはCtrl+クリックで手入力するときも範囲へ収めるために付けています。それでも保存ファイルやスクリプトから不正値が入る可能性はあるため、**UIだけを唯一の検証場所にしない**ようにしましょう。"],"id":"engine-transform-inspector-section-4"},{"title":"選択変更と、編集中の値をどう扱う？","paragraphs":["別のEntityを選んだときは、そのEntityのTransformを毎フレーム渡します。選択前のポインターをInspectorが長く保持せず、IDから対象を解決する方が削除にも対応しやすくなります。","Undoを追加するときは、DragFloat3のtrueごとに履歴を作るのではなく、編集を始める直前の値を保持し、編集が終わったタイミングでひとつの操作として確定します。複数軸ウィジェットの扱いはUndoの記事で整理しましょう。","複数のEntityを切り替える実装では、Inspectorの呼び出し側をEntityの安定IDでPushID/PopIDして、別の対象へ同じ入力欄の編集中状態を持ち越さないようにします。選択を切り替える前に、未確定の編集を確定するか取り消すかも決めておきましょう。"],"id":"engine-transform-inspector-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Cubos Team: Inspectorで型ごとの表示を拡張する実例","url":"https://cubos.riscadoa.com/blog/release-07/"}],"image":"guide-engine-workbench","image_scene":"example-engine-transform-inspector-02","image_caption":""},{"id":"engine-viewport-picking","category":"engine","level":"advanced","minutes":25,"title":"Sceneビューをクリックして選択する：画像座標からピクセルへ","summary":"ゲーム画面をImageで表示したら、次はクリック位置をレンダーターゲットの座標へ変換してみましょう。余白・DPI・上下反転を順番に整理します。","related_api":["ImGui::Image","ImGui::GetItemRectMin","ImGui::GetItemRectMax","ImGui::IsItemHovered","ImGui::GetMousePos","ImGui::IsMouseClicked"],"related_guides":["image-texture","image-dx11","image-dx12","extensions-imguizmo","engine-input-focus","visual-pan-zoom","visual-atlas-viewer"],"tags":["Viewport","ピッキング","レンダーターゲット","座標変換"],"sections":[{"title":"SceneとGameは、同じ画像でなくてもいい","paragraphs":["Sceneビューは編集用カメラ、Gameビューはゲーム内カメラの結果を表示する、という構成がよく使われます。ImGui側はその違いを知る必要がなく、アプリが用意したテクスチャをImage()で表示します。","ピッキングにも複数の実装があります。カメラからレイを飛ばす方法や、物体IDを別のレンダーターゲットへ書いて読み戻す方法です。ここでは共通の入口となる**画像上のクリック位置 → 描画先のピクセル座標**だけを実装します。"],"id":"engine-viewport-picking-section-1"},{"title":"ウィンドウ位置ではなく、Imageの四隅を基準にする","paragraphs":["次の関数は有効なウィンドウ内で呼びます。textureはアプリが作成した有効なテクスチャ参照、widthとheightは実際の描画先のピクセル数です。Imageの余白と枠を除くため、枠線の幅をこの呼び出し中だけ0にしています。","GetItemRectMin/Max()は必ずImage()の直後に読みます。間にText()を置くと「直前の項目」が変わってしまいます。uvを反転した場合は、ピッキングのvも同じ向きへ戻します。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <cmath>\n#include <optional>\n    struct PickPixel\n    {\n        int x;\n        int y;\n    };\n    std::optional<PickPixel> DrawSceneImage(\n        ImTextureRef texture, int width, int height, bool flip_y)\n    {\n        if (width <= 0 || height <= 0)\n            return std::nullopt;\n        const ImVec2 available = ImGui::GetContentRegionAvail();\n        if (available.x <= 0.0f || available.y <= 0.0f)\n            return std::nullopt;\n        const float scale = std::min(available.x / width, available.y / height);\n        ImGui::PushStyleVar(ImGuiStyleVar_ImageBorderSize, 0.0f);\n        ImGui::Image(texture,\n            ImVec2(width * scale, height * scale),\n            flip_y ? ImVec2(0, 1) : ImVec2(0, 0),\n            flip_y ? ImVec2(1, 0) : ImVec2(1, 1));\n        ImGui::PopStyleVar();\n        const ImVec2 top_left = ImGui::GetItemRectMin();\n        const ImVec2 bottom_right = ImGui::GetItemRectMax();\n        if (!ImGui::IsItemHovered() ||\n            !ImGui::IsMouseClicked(ImGuiMouseButton_Left))\n            return std::nullopt;\n        const ImVec2 mouse = ImGui::GetMousePos();\n        const float u = (mouse.x - top_left.x) / (bottom_right.x - top_left.x);\n        float v = (mouse.y - top_left.y) / (bottom_right.y - top_left.y);\n        if (u < 0.0f || u >= 1.0f || v < 0.0f || v >= 1.0f)\n            return std::nullopt;\n        if (flip_y)\n            v = 1.0f - v;\n        return PickPixel{\n            std::clamp(static_cast<int>(std::floor(u * width)), 0, width - 1),\n            std::clamp(\n                static_cast<int>(std::floor(v * height)), 0, height - 1)};\n    }","id":"engine-viewport-picking-section-2","capture":{"guide_id":"engine-viewport-picking","section_index":1,"scene":"example-engine-viewport-picking-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"df8c22521f749433b7fd3133baae797f8cb9cfa0270dd1c04909e39ba32be25f","image_sha256":"1a597a486a7415f00dfd77c5103d9fdf6f7aa1f030dbf11f34992ad0044a568a","fixture":"auto pixel=DrawSceneImage(Texture(),256,256,false); if(pixel) ImGui::SetTooltip(\"Picked pixel: %d, %d\",pixel->x,pixel->y);","initialization":""}},{"title":"DPIは、表示座標と描画先サイズを分けると整理しやすい","paragraphs":["マウス位置とGetItemRectMin/Max()は同じImGuiの画面座標で比べます。上の比率計算にDPI倍率をもう一度掛ける必要はありません。画像の横幅の半分をクリックしたら、描画先が何ピクセルでもuは0.5になります。","高DPI環境でレンダーターゲットを何ピクセルにするかは別の判断です。次は表示領域と、アプリが把握する対応するフレームバッファー倍率からサイズを決める例です。Multi-viewportではメインウィンドウの倍率をすべてへ流用せず、対象OSウィンドウの倍率を渡してください。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <cmath>\n    struct TargetExtent\n    {\n        int width;\n        int height;\n    };\n    TargetExtent ChooseTargetExtent(\n        ImVec2 content_size, ImVec2 framebuffer_scale)\n    {\n        const float width = std::max(content_size.x, 1.0f) *\n                            std::max(framebuffer_scale.x, 0.1f);\n        const float height = std::max(content_size.y, 1.0f) *\n                             std::max(framebuffer_scale.y, 0.1f);\n        return {std::clamp(static_cast<int>(std::lround(width)), 1, 8192),\n            std::clamp(static_cast<int>(std::lround(height)), 1, 8192)};\n    }","id":"engine-viewport-picking-section-3","capture":{"guide_id":"engine-viewport-picking","section_index":2,"scene":"example-engine-viewport-picking-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"417488fa31376b48a2ded830310b8c7428851d352958206b2238703707f75eb5","image_sha256":"f1ed384aaeb2f0c163c77c7112421f2cd2351766d29610949ff23876dcbdec4f","fixture":"auto value=ChooseTargetExtent(ImVec2(640,360),ImVec2(1.5f,1.5f)); ImGui::TextUnformatted(\"Input: content 640 x 360 / framebuffer scale 1.5\"); ImGui::Separator(); ImGui::Text(\"Render target: %d x %d\",value.width,value.height);","initialization":""}},{"title":"GPUの読み戻し結果は、少し遅れて届くかもしれない","paragraphs":["IDバッファーを使う場合、クリックした瞬間にGPU待ちをすると画面が引っかかることがあります。実際のエンジンでは読み戻しを非同期にし、要求時のシーンID、描画先の世代、マウス座標を一緒に保持する設計を検討します。","結果が届く前にシーンを閉じたり、物体を削除したりすることもあります。**返ってきたIDが今も有効かを検証してから選択を更新**しましょう。Image()がピクセルを読んだり、3D物体を選択してくれるわけではありません。"],"id":"engine-viewport-picking-section-4"},{"title":"四隅を押してから、ギズモへ進もう","paragraphs":["まず左上・右上・左下・右下をクリックして、期待したピクセルへ変換されるか確かめます。次にウィンドウのサイズ変更と表示倍率変更を試し、画像外の余白ではピックしないことを確認しましょう。"],"bullets":["ピッキング対象の画像とIDバッファーは同じカメラ、同じ描画範囲、同じサイズに揃えます。","カメラ操作やImGuizmoの操作中は選択ピックを抑制し、1回のクリックが複数操作へ流れないよう優先順位を決めます。","部分UVでテクスチャを切り出す場合は、0〜1の画像座標をそのUV範囲へ写してからピクセルへ変換します。"],"id":"engine-viewport-picking-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-viewport-picking-02","image_caption":""},{"id":"engine-play-modes","category":"engine","level":"advanced","minutes":22,"title":"Play・Pause・Stepを付ける：編集したシーンを守って試す","summary":"ちょっと動かして、止めて、1フレームだけ進める。ゲームを試しやすくしながら、編集中のシーンをうっかり上書きしない仕組みを作ります。","related_api":["ImGui::Button","ImGui::BeginDisabled","ImGui::EndDisabled","ImGui::SameLine","ImGui::Text"],"related_guides":["engine-editor-architecture","engine-input-focus","engine-safe-deletion"],"tags":["Playモード","Pause","Step","シーン複製"],"sections":[{"title":"ボタンより先に、3つの状態を決めよう","paragraphs":["ここではEdit、Playing、Pausedの3状態を用意します。Editでは編集用データを操作し、Playingでは実行用データを更新し、Pausedでは実行用データを表示したまま更新を止めます。StepはPausedのときだけ、決めた時間ぶん更新する操作です。","**UIの更新とゲームの更新は別**です。Pause中もNewFrame()からUI描画までを続けないと、再開ボタンまで動かなくなってしまいます。音声や物理も止めるなら、各システムへ状態を伝える処理はアプリ側で用意します。"],"id":"engine-play-modes-section-1"},{"title":"状態遷移が見える、小さな実験を作る","paragraphs":["次の例は数値xを動かすだけの試作です。Playingは呼び出し元のdelta_seconds、Stepは1/60秒ぶん進めます。本物の固定更新では、Stepを「固定更新1回」に結び付けてください。"],"code":"#include \"imgui.h\"\n    enum class RunMode\n    {\n        Edit,\n        Playing,\n        Paused\n    };\n    struct SimulationState\n    {\n        RunMode mode = RunMode::Edit;\n        float x = 0.0f;\n    };\n    void DrawSimulationControls(SimulationState & state, float delta_seconds)\n    {\n        bool step = false;\n        if (ImGui::Begin(\"Playback\"))\n        {\n            if (state.mode == RunMode::Edit)\n            {\n                if (ImGui::Button(\"Play\"))\n                    state.mode = RunMode::Playing;\n            }\n            else\n            {\n                if (ImGui::Button(\"Stop\"))\n                    state.mode = RunMode::Edit;\n                ImGui::SameLine();\n                if (ImGui::Button(\n                        state.mode == RunMode::Playing ? \"Pause\" : \"Resume\"))\n                    state.mode = state.mode == RunMode::Playing\n                                     ? RunMode::Paused\n                                     : RunMode::Playing;\n                ImGui::SameLine();\n                ImGui::BeginDisabled(state.mode != RunMode::Paused);\n                step = ImGui::Button(\"Step\");\n                ImGui::EndDisabled();\n            }\n            ImGui::Text(\"Position: %.3f\", state.x);\n        }\n        ImGui::End();\n        if (state.mode == RunMode::Playing)\n            state.x += delta_seconds;\n        else if (state.mode == RunMode::Paused && step)\n            state.x += 1.0f / 60.0f;\n    }","id":"engine-play-modes-section-2","capture":{"guide_id":"engine-play-modes","section_index":1,"scene":"example-engine-play-modes-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"37d3d14e139cd15507184a4fe4dc47f59d2eaacd2e12cc63b823bb359b674ea3","image_sha256":"26ee24a5169ba7a67d1afd6da8507e4d63a1d271949e507d3a3f526427f13f06","fixture":"static SimulationState state; DrawSimulationControls(state,ImGui::GetIO().DeltaTime);","initialization":""}},{"title":"Playを押したら、実行用のシーンを複製する","paragraphs":["上の試作は同じxを使っていますが、ゲーム用には編集シーンと実行シーンを分けましょう。次は値だけを持つ小さなSceneをコピーし、停止時に実行シーンを破棄する例です。Saveの対象は常にedit_sceneと決めておくと、実行中の落下位置を保存する事故を防げます。","この例のvectorは値コピーで独立します。実際のシーンにポインター、物理ボディ、GPUリソース、スクリプトがある場合は、単なるコピー代入だけでは不十分です。**共有してよいアセットと、実行ごとに作る状態を区別**してください。"],"code":"#include \"imgui.h\"\n#include <optional>\n#include <vector>\n    struct SceneEntity\n    {\n        int id;\n        float height;\n    };\n    struct SceneData\n    {\n        std::vector<SceneEntity> entities;\n    };\n    struct EditorSession\n    {\n        SceneData edit_scene;\n        std::optional<SceneData> play_scene;\n    };\n    void DrawSceneSession(EditorSession & session)\n    {\n        if (!session.play_scene)\n        {\n            if (ImGui::Button(\"Play copy\"))\n                session.play_scene = session.edit_scene;\n        }\n        else\n        {\n            if (ImGui::Button(\"Stop and discard runtime changes\"))\n                session.play_scene.reset();\n        }\n        ImGui::TextUnformatted(\n            session.play_scene ? \"Runtime copy\" : \"Editing source\");\n    }","id":"engine-play-modes-section-3","capture":{"guide_id":"engine-play-modes","section_index":2,"scene":"example-engine-play-modes-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"ec4f1b4e6ca7ea7727b6f0679130f65cf63534f74bcf10c849b3cc01bc2d8ece","image_sha256":"59aa65748d8e6b8a7ff5d84ef24a16e9e19112c2a8c115ad2e73a0907b517a86","fixture":"static EditorSession session; DrawSceneSession(session);","initialization":""}},{"title":"再開した瞬間に、大きく時間が進むのを防ぐ","paragraphs":["Pauseしていた実時間をそのまま次のdelta timeへ入れると、再開直後に物体が飛ぶことがあります。ゲーム時計を独立させ、Pause中の時間は進めないか、固定更新のアキュムレーターを適切に扱います。","Play開始・停止時には、選択中Entityがどちらのシーンに属するかも見直します。同じ数値IDがあっても別インスタンスなので、シーンIDを含む選択にするか、開始・終了時に選択を明示的に変換または解除しましょう。"],"id":"engine-play-modes-section-4"},{"title":"「停止したら何が戻るか」を先に決めよう","paragraphs":["位置やHPを元へ戻すのか、カメラ位置は維持するのか、実行中に編集したパラメーターを残すのか。どれもエディターの方針です。最初は「停止すると実行中の変更をすべて破棄」で揃え、必要になった値だけ後から適用できるようにすると分かりやすくなります。"],"bullets":["Playing中のInspectorを読み取り専用にするだけでも、編集先の混同を減らせます。","Stepが物理の固定更新なのか描画フレームなのかを表示に明記しましょう。","セーブ、Undo、選択、ゲーム入力を、モード切り替え時のチェックリストに入れておきましょう。"],"id":"engine-play-modes-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-play-modes-02","image_caption":""},{"id":"engine-undo-redo","category":"engine","level":"advanced","minutes":27,"title":"ドラッグ1回をUndo1回にする：編集の始まりと終わりをつかむ","summary":"スライダーを少し動かしただけで履歴が何十件も増える。そんなUndoを避けるために、ひとまとまりの編集として記録してみましょう。","related_api":["ImGui::DragFloat","ImGui::IsItemActivated","ImGui::IsItemDeactivated","ImGui::IsItemDeactivatedAfterEdit","ImGui::BeginDisabled"],"related_guides":["edit-commit","engine-transform-inspector","extensions-imguizmo","engine-safe-deletion"],"tags":["Undo","Redo","トランザクション","編集確定"],"sections":[{"title":"trueが返るたびに履歴へ積まない","paragraphs":["DragFloat()は操作中に値が変わるたびtrueを返します。このたびにUndoへ積むと、1回のドラッグを戻すのに何度もUndoを押すことになります。ここでは**編集開始前の値を覚え、編集終了時に1件だけ記録**する流れを作ります。","開始はIsItemActivated()、編集後の終了はIsItemDeactivatedAfterEdit()で調べます。どちらも直前の項目を調べるので、対象ウィジェットの直後に呼びます。選択の切り替えやUIが消えるケースは別途扱う必要があります。"],"id":"engine-undo-redo-section-1"},{"title":"単一のfloatで、履歴の境界を試す","paragraphs":["before_frameはウィジェットを呼ぶ前の値です。操作が始まったフレームに値も変わる可能性があるので、IsItemActivated()の後に現在値を保存するだけでは遅い場合があります。","以下の型と関数をまとめて使います。履歴はアプリ側が保持し、この関数には毎回同じ項目の値を渡します。別Entityへ切り替えるときの扱いは次の段落で決めましょう。"],"code":"#include \"imgui.h\"\n#include <vector>\n    struct FloatCommand\n    {\n        float before;\n        float after;\n    };\n    struct FloatHistory\n    {\n        std::vector<FloatCommand> undo;\n        std::vector<FloatCommand> redo;\n        bool editing = false;\n        float edit_start = 0.0f;\n    };\n    bool DrawTransactionalFloat(float& value, FloatHistory& history)\n    {\n        const float before_frame = value;\n        const bool changed = ImGui::DragFloat(\"Speed\", &value, 0.1f);\n        if (ImGui::IsItemActivated())\n        {\n            history.editing = true;\n            history.edit_start = before_frame;\n        }\n        if (ImGui::IsItemDeactivatedAfterEdit() && history.editing)\n        {\n            if (history.edit_start != value)\n            {\n                history.undo.push_back({history.edit_start, value});\n                history.redo.clear();\n            }\n        }\n        if (ImGui::IsItemDeactivated())\n            history.editing = false;\n        return changed;\n    }","id":"engine-undo-redo-section-2","capture":{"guide_id":"engine-undo-redo","section_index":1,"scene":"example-engine-undo-redo-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"959250a91b0d6bd8cd18e3f0cfecb57f05979c9cbc04c5a67f2c309b1fd285a4","image_sha256":"8ad7f5d994292820eae2760c36385032c1fe3b04b4ecf9c5a20748cb1e7926c8","fixture":"static float value=1.0f; static FloatHistory history; DrawTransactionalFloat(value,history); ImGui::Text(\"Undo entries: %zu / Redo entries: %zu\",history.undo.size(),history.redo.size());","initialization":""}},{"title":"UndoとRedoは、前後の値を入れ替える操作","paragraphs":["次は独立した、履歴を適用するための最小モデルです。Buttonの無効化は操作できない理由を表し、関数側でも履歴の空判定を行います。実際には履歴操作中に新しい編集操作を始めないよう、編集中の確定方針もつなぎます。"],"code":"#include \"imgui.h\"\n#include <vector>\n    struct ScalarCommand\n    {\n        float before;\n        float after;\n    };\n    struct ScalarHistory\n    {\n        std::vector<ScalarCommand> undo;\n        std::vector<ScalarCommand> redo;\n    };\n    void DrawUndoRedo(float& value, ScalarHistory& history)\n    {\n        ImGui::BeginDisabled(history.undo.empty());\n        const bool undo_requested = ImGui::Button(\"Undo\");\n        ImGui::EndDisabled();\n        if (undo_requested && !history.undo.empty())\n        {\n            const ScalarCommand command = history.undo.back();\n            history.undo.pop_back();\n            value = command.before;\n            history.redo.push_back(command);\n        }\n        ImGui::SameLine();\n        ImGui::BeginDisabled(history.redo.empty());\n        const bool redo_requested = ImGui::Button(\"Redo\");\n        ImGui::EndDisabled();\n        if (redo_requested && !history.redo.empty())\n        {\n            const ScalarCommand command = history.redo.back();\n            history.redo.pop_back();\n            value = command.after;\n            history.undo.push_back(command);\n        }\n    }","id":"engine-undo-redo-section-3","capture":{"guide_id":"engine-undo-redo","section_index":2,"scene":"example-engine-undo-redo-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"2f20e6aa1e5e0e2ae44e996e9d7b370a0184bddc4ab923b8f0615e9a0de39e65","image_sha256":"4ff0ed457065216e08b5dec5d94893fc8906e4a86293b8e931f8aa17b66c0de9","fixture":"static float value=2.0f; static ScalarHistory history; if(capture_frame==0)history.undo.push_back({1.0f,2.0f}); DrawUndoRedo(value,history); ImGui::Text(\"Current value: %.1f / Undo: %zu / Redo: %zu\",value,history.undo.size(),history.redo.size());","initialization":""}},{"title":"項目が消えたときにも、編集中の操作を閉じよう","paragraphs":["別Entityを選んだりInspectorを閉じたりしてウィジェット自体が呼ばれなくなると、その項目のIsItemDeactivatedAfterEdit()をこの関数内で拾えません。**選択変更・パネル終了・シーン切り替えの入口でも、進行中の編集を確定か取り消し**できるようにします。","実際のコマンドには対象のEntity ID、プロパティID、前後の値を保存します。UndoのたびにIDから対象を解決し、削除やシーン切り替えで無効になっていた場合の処理も決めてください。生ポインターを履歴へ残すと、後から解放済みメモリーを触る原因になります。"],"id":"engine-undo-redo-section-4"},{"title":"複数軸やギズモは「ひとつの操作」を定義する","paragraphs":["DragFloat3は内部に複数の入力項目を持つため、単一DragFloatの例をそのまま貼るだけで全軸が1件になるとは限りません。最初はX/Y/Zを別のDragFloatとして扱うか、各軸の編集状態をまとめてTransform全体の操作を開始・確定する管理を用意しましょう。","ImGuizmoなら「操作開始から操作終了まで」を同じ履歴サービスへ渡します。ComboやSelectableでは値が変わらない選択でもIsItemDeactivatedAfterEdit()がtrueになることがあるため、最後に前後の値が実際に違うか調べるのも大切です。"],"id":"engine-undo-redo-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-undo-redo-02","image_caption":""},{"id":"engine-content-browser","category":"engine","level":"intermediate","minutes":20,"title":"Content Browserを作ろう：ファイル名よりアセットIDでつなぐ","summary":"画像やマテリアルを一覧から選ぶ画面を作ります。検索、開く操作、読み込み中の表示まで、あとから育てやすい形で始めましょう。","related_api":["ImGui::BeginTable","ImGui::Selectable","ImGui::IsMouseDoubleClicked","ImGui::PushID","ImGui::ProgressBar","ImGui::TextUnformatted"],"related_guides":["engine-drag-drop","image-texture","tables-sorting"],"tags":["Content Browser","アセット","検索","非同期読み込み"],"sections":[{"title":"UIに渡すのは、アセット台帳のスナップショット","paragraphs":["ファイルシステムを毎フレーム走査するところから始めると、大きなフォルダーでUIが固まりやすくなります。アプリ側でアセット台帳を用意し、UIは表示名、種類、IDを読むだけにすると分担が分かりやすくなります。","**表示名やファイルパスと、アセットの識別子を分けましょう。** 名前変更や移動でもIDを維持する設計なら、マテリアルが参照している画像がすぐ迷子になりません。IDの発行・保存・パスとの対応付けはImGuiの機能ではなく、アセット管理側の仕事です。"],"id":"engine-content-browser-section-1"},{"title":"検索できる、2列の一覧から始める","paragraphs":["フィルターと選択IDは呼び出し元が保持します。ダブルクリックされたIDを返すだけにして、実際に画像ビューアーやマテリアル画面を開く処理は呼び出し元へ任せます。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <string>\n#include <vector>\n    struct AssetRow\n    {\n        std::uint64_t id;\n        std::string name;\n        std::string kind;\n    };\n    std::optional<std::uint64_t> DrawAssetBrowser(\n        const std::vector<AssetRow>& assets,\n        ImGuiTextFilter& filter,\n        std::uint64_t& selected_id)\n    {\n        std::optional<std::uint64_t> open_request;\n        filter.Draw(\"Search\");\n        if (ImGui::BeginTable(\"Assets\", 2, ImGuiTableFlags_RowBg))\n        {\n            ImGui::TableSetupColumn(\"Name\");\n            ImGui::TableSetupColumn(\"Type\");\n            ImGui::TableHeadersRow();\n            for (const AssetRow& asset : assets)\n            {\n                if (!filter.PassFilter(asset.name.c_str()))\n                    continue;\n                const std::string id = std::to_string(asset.id);\n                ImGui::PushID(id.c_str());\n                ImGui::TableNextRow();\n                ImGui::TableSetColumnIndex(0);\n                const std::string label = asset.name + \"###asset\";\n                if (ImGui::Selectable(label.c_str(),\n                        selected_id == asset.id,\n                        ImGuiSelectableFlags_AllowDoubleClick))\n                {\n                    selected_id = asset.id;\n                    if (ImGui::IsMouseDoubleClicked(ImGuiMouseButton_Left))\n                        open_request = asset.id;\n                }\n                ImGui::TableSetColumnIndex(1);\n                ImGui::TextUnformatted(asset.kind.c_str());\n                ImGui::PopID();\n            }\n            ImGui::EndTable();\n        }\n        return open_request;\n    }","id":"engine-content-browser-section-2","capture":{"guide_id":"engine-content-browser","section_index":1,"scene":"example-engine-content-browser-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"08ca29e5554b32f259fdfc0370b4dee2ed5d211de6ebb3a8c90fda8c7dcee639","image_sha256":"97b4ad368c2248fcf2ce53689c42764b84acd512ef867a15b68ee2ce5a08b1b4","fixture":"static std::vector<AssetRow> assets{{101,\"Player.mesh\",\"Mesh\"},{102,\"Ground.mat\",\"Material\"},{103,\"Checker.png\",\"Texture\"},{104,\"Main.scene\",\"Scene\"}}; static ImGuiTextFilter filter; static std::uint64_t selected=103; DrawAssetBrowser(assets,filter,selected);","initialization":""}},{"title":"読み込み中も、画面は動くようにする","paragraphs":["重い読み込みはアプリのジョブへ依頼し、UIには状態だけ渡します。下の例は状態の表示だけを担当し、スレッドの起動や同期を隠れた前提にしません。ワーカーとUIが同じ文字列やvectorを同時に書き換えないよう、スナップショットやキューで受け渡しましょう。"],"code":"#include \"imgui.h\"\n#include <algorithm>\n#include <string>\n    enum class ImportState\n    {\n        Idle,\n        Loading,\n        Ready,\n        Failed\n    };\n    struct ImportSnapshot\n    {\n        ImportState state = ImportState::Idle;\n        float progress = 0.0f;\n        std::string message;\n    };\n    void DrawImportStatus(const ImportSnapshot& snapshot)\n    {\n        switch (snapshot.state)\n        {\n        case ImportState::Idle:\n            ImGui::TextUnformatted(\"Select an asset to load.\");\n            break;\n        case ImportState::Loading:\n            ImGui::ProgressBar(std::clamp(snapshot.progress, 0.0f, 1.0f));\n            ImGui::TextUnformatted(snapshot.message.c_str());\n            break;\n        case ImportState::Ready:\n            ImGui::TextUnformatted(\"Ready\");\n            break;\n        case ImportState::Failed:\n            ImGui::TextColored(\n                ImVec4(1.0f, 0.35f, 0.25f, 1.0f), \"Import failed\");\n            ImGui::TextWrapped(\"%s\", snapshot.message.c_str());\n            break;\n        }\n    }","id":"engine-content-browser-section-3","capture":{"guide_id":"engine-content-browser","section_index":2,"scene":"example-engine-content-browser-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"b44cb8442f29790f63215474983785535d650ea8c0e6f48d587efc01d31b9f6a","image_sha256":"72def41baf499401a3f39d0c1c3a01b39ef0d6aa92f20b0e2901a6f1dd6806be","fixture":"ImportSnapshot value; value.state=ImportState::Loading; value.progress=0.65f; value.message=\"Importing Player.mesh (sample job status)\"; DrawImportStatus(value);","initialization":""}},{"title":"サムネイルは、ファイルをImageに渡す機能ではない","paragraphs":["サムネイルを付けるときは、画像のデコードとGPUテクスチャ作成をアセット管理側で行い、その有効な参照をImage()へ渡します。ファイルパスをそのまま渡すことはできません。","画面外のアセットまで毎フレーム読み込み直さず、キャッシュと破棄方針を用意しましょう。**描画で参照したGPUリソースは、GPUの使用が終わるまで生かす**必要があります。選択変更の瞬間に解放するだけでは間に合わないことがあります。"],"id":"engine-content-browser-section-4"},{"title":"次は、Inspectorへドラッグして渡してみよう","paragraphs":["選択と開く操作が安定したら、アセットIDをドラッグ＆ドロップで渡せます。受け取り先が画像、マテリアル、シーンのどれを受け付けるかもアプリ側で検証すると、分かりにくい型違いを減らせます。"],"bullets":["ファイル名は外部データなので、Text(name)ではなくTextUnformatted(name)やText(\"%s\", name)を使います。","大量の一覧は、検索結果を一度組み立ててから必要な行を表示する方針へ進めます。","読み込み失敗は空白のサムネイルだけにせず、状態と短い理由を一緒に見せましょう。"],"id":"engine-content-browser-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"自作エンジン作者の開発記録: アセットとInspectorをつなぐ画面例","url":"https://hanion.dev/post/enik-engine/"}],"image":"guide-engine-workbench","image_scene":"example-engine-content-browser-02","image_caption":""},{"id":"engine-drag-drop","category":"engine","level":"advanced","minutes":22,"title":"物体やアセットをドラッグで渡す：PayloadにはIDを入れよう","summary":"Hierarchyから参照先を選んだり、画像をマテリアルへ割り当てたり。ドラッグ操作を、壊れにくいデータの受け渡しにつなぎます。","related_api":["ImGui::BeginDragDropSource","ImGui::SetDragDropPayload","ImGui::EndDragDropSource","ImGui::BeginDragDropTarget","ImGui::AcceptDragDropPayload","ImGui::EndDragDropTarget"],"related_guides":["engine-content-browser","engine-hierarchy-ids","engine-undo-redo"],"tags":["ドラッグ＆ドロップ","Payload","Asset ID","Entity参照"],"sections":[{"title":"コピーされるのは、渡したバイト列","paragraphs":["SetDragDropPayload()は渡したデータをImGui内部へコピーします。だから小さなIDを値で渡す方法は扱いやすい一方、std::stringやvectorのオブジェクトを丸ごとコピーして、受け取り側でそのまま復元する使い方はできません。","**ポインターより、解決し直せるIDを送る**と寿命を扱いやすくなります。Entityならシーンと世代、Assetなら台帳で管理するIDを含めるなど、対象を間違えない情報を設計しましょう。Payloadの型名は最大32文字で、先頭が_の名前はImGui内部用です。"],"id":"engine-drag-drop-section-1"},{"title":"まずは、同じプロジェクト内のアセットIDを渡す","paragraphs":["次は1つの送信元と受信先を作る独立した例です。受け取ったIDを返しますが、この段階ではマテリアルへの適用は行いません。呼び出し元が台帳で実在と型を調べた後、編集要求として反映します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <cstring>\n#include <optional>\n    std::optional<std::uint64_t> DrawAssetDropExample(std::uint64_t asset_id)\n    {\n        ImGui::Button(\"Drag asset\");\n        if (ImGui::BeginDragDropSource())\n        {\n            ImGui::SetDragDropPayload(\n                \"EDITOR_ASSET_ID\", &asset_id, sizeof(asset_id));\n            ImGui::Text(\n                \"Asset %llu\", static_cast<unsigned long long>(asset_id));\n            ImGui::EndDragDropSource();\n        }\n        ImGui::Button(\"Drop texture here\");\n        std::optional<std::uint64_t> result;\n        if (ImGui::BeginDragDropTarget())\n        {\n            if (const ImGuiPayload* payload =\n                    ImGui::AcceptDragDropPayload(\"EDITOR_ASSET_ID\"))\n            {\n                if (payload->DataSize == sizeof(std::uint64_t))\n                {\n                    std::uint64_t received = 0;\n                    std::memcpy(&received, payload->Data, sizeof(received));\n                    result = received;\n                }\n            }\n            ImGui::EndDragDropTarget();\n        }\n        return result;\n    }","id":"engine-drag-drop-section-2","capture":{"guide_id":"engine-drag-drop","section_index":1,"scene":"example-engine-drag-drop-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"6c399487b61a642e95b29470f59c002285774a66150df0c78e827d87ed1ac8e0","image_sha256":"5f0eea89b4979f86a19f5399732146734e22e2624dda49b9f2b4851002654fe3","fixture":"DrawAssetDropExample(103);","initialization":""}},{"title":"Entity参照には、所属シーンも持たせる","paragraphs":["ID番号が同じでも、別のシーンの物体かもしれません。次は所属シーンと世代番号も付けたPayloadの型です。送信側もこの型をEDITOR_ENTITY_REFという型名でSetDragDropPayload()へ渡します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <cstring>\n#include <optional>\n#include <type_traits>\n    struct EntityReference\n    {\n        std::uint64_t scene_id;\n        std::uint32_t entity_id;\n        std::uint32_t generation;\n    };\n    static_assert(std::is_trivially_copyable<EntityReference>::value,\n        \"Payload must be bytes\");\n    std::optional<EntityReference> ReadEntityDrop(std::uint64_t active_scene_id)\n    {\n        std::optional<EntityReference> result;\n        if (ImGui::BeginDragDropTarget())\n        {\n            if (const ImGuiPayload* payload =\n                    ImGui::AcceptDragDropPayload(\"EDITOR_ENTITY_REF\"))\n            {\n                if (payload->DataSize == sizeof(EntityReference))\n                {\n                    EntityReference reference{};\n                    std::memcpy(&reference, payload->Data, sizeof(reference));\n                    if (reference.scene_id == active_scene_id)\n                        result = reference;\n                }\n            }\n            ImGui::EndDragDropTarget();\n        }\n        return result;\n    }","id":"engine-drag-drop-section-3","capture":{"guide_id":"engine-drag-drop","section_index":2,"scene":"example-engine-drag-drop-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"e7230bd4f3d53760286fb3511d2b176b9a2f9a9bfea0739ff7bbcdec3b922c5e","image_sha256":"2ba30abf4941706d9540a9ecf4c745234bce8d9287689e4d7c39f69fbe5dddcd","fixture":"ImGui::Button(\"Entity reference target\",ImVec2(320,60)); auto value=ReadEntityDrop(42); ImGui::TextUnformatted(value?\"Accepted entity\":\"Drag a matching scene/entity payload onto the target.\");","initialization":""}},{"title":"プレビューと、実際の確定は分ける","paragraphs":["通常のAcceptDragDropPayload()は、ドロップが確定したタイミングで受け取る使い方です。AcceptBeforeDeliveryを付けると離す前にも内容を見られますが、その段階で本当の値を毎フレーム書き換えないようにしましょう。確定時はpayload->IsDelivery()で判定します。","受信したImGuiPayload*やpayload->Dataを長期保存しないでください。必要なIDの値を自分のデータへコピーし、後からレジストリーで有効性を調べます。**型名が一致していても、サイズ・所属・対象の存在と用途を検証**するのが受け取り側の役目です。"],"id":"engine-drag-drop-section-4"},{"title":"親の付け替えには、もうひとつ検証が必要","paragraphs":["Hierarchyの親子付け替えで使うなら、自分を自分の子にしたり、子孫を新しい親にしたりする操作を拒否します。この循環チェックはドラッグ＆ドロップAPIでは行われません。","受け取りをUI内で即実行せず、SetParentやSetAssetの編集要求へ変換しておくと、Undoやシーンのdirty更新も同じ入口へまとめられます。BeginDragDropSource/Target()がtrueのときだけ、対応するEndを呼ぶ点も忘れずに揃えましょう。"],"id":"engine-drag-drop-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: 状態管理・入力・アプリ側の責任","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-drag-drop-02","image_caption":""},{"id":"engine-material-light","category":"engine","level":"intermediate","minutes":20,"title":"マテリアルとライトをその場で調整する：見た目と値を結び付ける","summary":"色、粗さ、光の強さを触りながらSceneで確かめる。見た目を作り込むためのInspectorを、小さな編集用モデルから作ります。","related_api":["ImGui::ColorEdit3","ImGui::SliderFloat","ImGui::DragFloat","ImGui::Checkbox","ImGui::SeparatorText","ImGui::SetItemTooltip"],"related_guides":["engine-transform-inspector","engine-undo-redo","engine-viewport-picking"],"tags":["マテリアル","ライト","PBR","色空間"],"sections":[{"title":"スライダーを動かす前に、どの値かを決めよう","paragraphs":["粗さ0〜1、金属度0〜1のように、シェーダーで使う値の意味をUIへそのまま伝えると調整しやすくなります。ImGuiが材質やライトの描画をするのではなく、**UIで変えた値をアプリがレンダラーへ渡す**という流れです。","色は特に注意が必要です。sRGBの画像テクセルと線形の色係数は同じ数値でも意味が違います。ColorEdit3()がエンジンの色空間を判断して自動変換してくれるわけではないので、編集データの規約を明示しましょう。"],"id":"engine-material-light-section-1"},{"title":"材質の基本3項目を、編集できるようにする","paragraphs":["下の例は線形のベースカラー係数を直接編集するモデルです。色スウォッチを最終レンダリングの見本と考えず、Sceneのプレビューで確認します。roughnessの下限0.04はこの試作用の方針で、glTFなどのデータ仕様そのものの下限を示す値ではありません。"],"code":"#include \"imgui.h\"\n    struct MaterialParameters\n    {\n        float base_color_linear[3] = {0.8f, 0.2f, 0.1f};\n        float roughness = 0.5f;\n        float metallic = 0.0f;\n        bool dirty = false;\n    };\n    bool DrawMaterialProperties(MaterialParameters & material)\n    {\n        ImGui::SeparatorText(\"Material\");\n        bool changed = ImGui::ColorEdit3(\"Base color (linear)\",\n            material.base_color_linear,\n            ImGuiColorEditFlags_Float);\n        ImGui::SetItemTooltip(\"Linear color factor. Check the scene preview.\");\n        changed |= ImGui::SliderFloat(\"Roughness\",\n            &material.roughness,\n            0.04f,\n            1.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        changed |= ImGui::SliderFloat(\"Metallic\",\n            &material.metallic,\n            0.0f,\n            1.0f,\n            \"%.3f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        material.dirty |= changed;\n        return changed;\n    }","id":"engine-material-light-section-2","capture":{"guide_id":"engine-material-light","section_index":1,"scene":"example-engine-material-light-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"dcfd459f1d6a29ce4cb7244170ee5457d13c49807a9d33f3188c48534aced987","image_sha256":"587d824ee9ce9fc12bff7bde6ee8e1e582a3f6fb9a408e6d3943d79cd87e8587","fixture":"static MaterialParameters value; DrawMaterialProperties(value);","initialization":""}},{"title":"HDRの光は、色と強さを分けると扱いやすい","paragraphs":["ライトでは色の比率と明るさの大きさを分けると、光の色を保ったまま強さを調整できます。次のIntensityは説明用の相対値です。実際のエンジンでルーメンやカンデラを採用するなら、ラベルと保存値の単位も合わせてください。","ColorEditFlags_HDRは1を超える値を扱うための指定で、HDRレンダーターゲットやトーンマッピングを自動で有効にする機能ではありません。見た目に反映する描画処理はレンダラー側の担当です。"],"code":"#include \"imgui.h\"\n    struct LightParameters\n    {\n        float color[3] = {1.0f, 0.95f, 0.85f};\n        float intensity = 5.0f;\n        bool casts_shadow = true;\n    };\n    bool DrawLightProperties(LightParameters & light)\n    {\n        ImGui::SeparatorText(\"Light\");\n        bool changed = ImGui::ColorEdit3(\"Color multiplier\",\n            light.color,\n            ImGuiColorEditFlags_Float | ImGuiColorEditFlags_HDR);\n        changed |= ImGui::DragFloat(\"Intensity (relative)\",\n            &light.intensity,\n            0.05f,\n            0.0f,\n            10000.0f,\n            \"%.2f\",\n            ImGuiSliderFlags_AlwaysClamp);\n        changed |= ImGui::Checkbox(\"Cast shadows\", &light.casts_shadow);\n        return changed;\n    }","id":"engine-material-light-section-3","capture":{"guide_id":"engine-material-light","section_index":2,"scene":"example-engine-material-light-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"1c8fe333594b45b48524e4ff78eba110a950bb6a6e0809ebf927b49d3b70e1e6","image_sha256":"b12376fbeb976114e9ccef10784bb6ba7542ab2bb2756575cc868ad027bd92f7","fixture":"static LightParameters value; DrawLightProperties(value);","initialization":""}},{"title":"GPUへ反映する入口を、1か所にまとめよう","paragraphs":["UIはCPU側の編集モデルを変更し、レンダラーがその変更を安全なタイミングでGPUへ送るようにします。コンスタントバッファーへの転送、ディスクリプター更新、シェーダー再生成などを各スライダーの中へ直接散らすと、同期や履歴の追加が難しくなります。","**表示用の値、保存する値、GPUへ送る値の関係を決めておく**と混乱が減ります。sRGB変換をUIとシェーダーで二重に掛けたり、露出を材質色へ焼き込んだりしないようにしましょう。"],"id":"engine-material-light-section-4"},{"title":"同じ条件で見比べられるプレビューを作る","paragraphs":["マテリアルの見た目を比較するときは、カメラ、背景、環境光、露出が揃ったプレビューがあると便利です。球と平面を置くだけでも、粗さや金属度の違いを見つけやすくなります。","次はリセット、変更前後の比較、Undoを加えてみましょう。「触ってみたけれど元の方が良かった」をすぐ戻せると、調整する人も安心して試せます。"],"id":"engine-material-light-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Khronos glTF: 線形の色係数とsRGBテクスチャの区別","url":"https://github.com/KhronosGroup/glTF/blob/main/specification/2.0/schema/material.pbrMetallicRoughness.schema.json"}],"image":"guide-engine-workbench","image_scene":"example-engine-material-light-02","image_caption":""},{"id":"engine-safe-deletion","category":"engine","level":"advanced","minutes":23,"title":"削除しても落ちないエディターへ：選択と参照の寿命をそろえる","summary":"物体を消した直後にInspectorでクラッシュ。原因を「ImGuiの不調」にせず、選択IDとデータの寿命から防いでいきましょう。","related_api":["ImGui::Selectable","ImGui::Button","ImGui::BeginDisabled","ImGui::TextUnformatted","ImGui::PushID"],"related_guides":["engine-hierarchy-ids","engine-undo-redo","engine-drag-drop","engine-play-modes"],"tags":["削除","寿命","世代付きハンドル","参照切れ"],"sections":[{"title":"UIは、前のフレームのポインターを覚えすぎない","paragraphs":["Inspectorが選択中コンポーネントの生ポインターを持ち続けると、削除やvectorの再確保で無効になることがあります。**選択はハンドルで保持し、使う直前に有効な対象へ解決する**と、失効をチェックする場所が明確になります。","ここでは配列のslotとgenerationを組み合わせます。同じslotへ別の物体を作ってもgenerationが違えば、古い選択から新しい物体を誤って編集せずに済みます。これはエンジン側の設計で、ImGuiが自動で保証する仕組みではありません。"],"id":"engine-safe-deletion-section-1"},{"title":"世代付きハンドルを、その都度解決する","paragraphs":["以下はslotを再利用する最小モデルです。Resolve()が返すポインターは、その場の表示処理だけで使います。あとで配列を増減する可能性がある場所をまたいで保持しないようにします。","Inspector全体もEntityの安定したハンドルでIDを分けます。編集中の対象を消す・選び直すときは、その編集を確定または取り消してから切り替えると、別のEntityへ入力が引き継がれるのを防げます。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <vector>\n    struct EntityHandle\n    {\n        std::uint32_t slot;\n        std::uint32_t generation;\n    };\n    struct EntitySlot\n    {\n        std::uint32_t generation = 1;\n        bool alive = false;\n        float speed = 1.0f;\n    };\n    EntitySlot* Resolve(std::vector<EntitySlot> & slots, EntityHandle handle)\n    {\n        if (handle.slot >= slots.size())\n            return nullptr;\n        EntitySlot& slot = slots[handle.slot];\n        return slot.alive && slot.generation == handle.generation ? &slot\n                                                                  : nullptr;\n    }\n    void DrawSelectedEntity(std::vector<EntitySlot> & slots,\n        std::optional<EntityHandle> & selection)\n    {\n        EntitySlot* entity = selection ? Resolve(slots, *selection) : nullptr;\n        if (!entity)\n        {\n            selection.reset();\n            ImGui::TextUnformatted(\"No valid selection\");\n            return;\n        }\n        ImGui::DragFloat(\"Speed\", &entity->speed, 0.1f);\n    }","id":"engine-safe-deletion-section-2","capture":{"guide_id":"engine-safe-deletion","section_index":1,"scene":"example-engine-safe-deletion-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"448633666de53c7aef64563c3a80f0100ad6d4246dbe48a913b6a861f1eaaca0","image_sha256":"374eed4ef4483371fd26eb381dea3f9b66f63912b14c26265a2be36b82c4f2ff","fixture":"static std::vector<EntitySlot> slots{{1,true,2.5f},{2,true,1.0f}}; static std::optional<EntityHandle> selected=EntityHandle{0,1}; DrawSelectedEntity(slots,selected); ImGui::Text(\"Selection valid: %s\",selected?\"yes\":\"no\");","initialization":""}},{"title":"削除は、全パネルが読み終わってから反映する","paragraphs":["Hierarchyを走査しながら同じ配列を消すと、ループと参照が壊れやすくなります。次の独立した例では、UIが削除要求を積み、呼び出し元が全パネルを処理した後にApplyDeleteQueue()を呼びます。世代が一致しない古い要求は無視します。"],"code":"#include \"imgui.h\"\n#include <cstdint>\n#include <optional>\n#include <vector>\n    struct DeleteHandle\n    {\n        std::uint32_t slot;\n        std::uint32_t generation;\n    };\n    struct DeleteSlot\n    {\n        std::uint32_t generation = 1;\n        bool alive = true;\n    };\n    void DrawDeleteButton(std::optional<DeleteHandle> selection,\n        std::vector<DeleteHandle> & queue)\n    {\n        ImGui::BeginDisabled(!selection.has_value());\n        if (ImGui::Button(\"Delete selected\") && selection)\n            queue.push_back(*selection);\n        ImGui::EndDisabled();\n    }\n    void ApplyDeleteQueue(std::vector<DeleteSlot> & slots,\n        std::vector<DeleteHandle> & queue,\n        std::optional<DeleteHandle> & selection)\n    {\n        for (const DeleteHandle handle : queue)\n        {\n            if (handle.slot >= slots.size())\n                continue;\n            DeleteSlot& slot = slots[handle.slot];\n            if (!slot.alive || slot.generation != handle.generation)\n                continue;\n            slot.alive = false;\n            ++slot.generation;\n            if (selection && selection->slot == handle.slot &&\n                selection->generation == handle.generation)\n                selection.reset();\n        }\n        queue.clear();\n    }","id":"engine-safe-deletion-section-3","capture":{"guide_id":"engine-safe-deletion","section_index":2,"scene":"example-engine-safe-deletion-03","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"b41c6055e317d77061640d8935bc91d77b7e53e04d5e34f6f92a99cd90351b5c","image_sha256":"aa55c7318d185ddf5ca495fc43dfdabb653fcbd3df70e93ad74e76ed8ae6cff6","fixture":"static std::vector<DeleteSlot> slots(3); static std::vector<DeleteHandle> queue; static std::optional<DeleteHandle> selected=DeleteHandle{0,1}; DrawDeleteButton(selected,queue); ApplyDeleteQueue(slots,queue,selected); ImGui::Text(\"Slot 0 alive: %s / selected: %s\",slots[0].alive?\"yes\":\"no\",selected?\"yes\":\"none\");","initialization":""}},{"title":"消すのは物体だけではない","paragraphs":["選択、Undo履歴、ドラッグPayload、親子関係、スクリプトの参照、非同期ピッキング結果も対象を指しているかもしれません。削除時にすべての参照を直接書き換えるか、アクセス時に無効を返すハンドルへ統一するかを決めましょう。","世代カウンターも有限です。上の例は説明を簡単にするため32bitの加算にしています。長期稼働や極端な再利用を想定する仕組みなら、世代の折り返しやID枯渇の方針も必要です。"],"id":"engine-safe-deletion-section-4"},{"title":"UIが安全でも、GPUの寿命は別に考える","paragraphs":["CPU上の物体を消せても、テクスチャやバッファーをGPUがまだ使っている場合があります。**UIの削除完了とGPUリソースの解放可能時点は別**なので、フェンスなど既存レンダラーの仕組みに従って遅延解放します。","テストでは、編集中のEntityの削除、Undoの直後の削除、ドロップ中の削除、Play停止時のシーン破棄を試しましょう。無効になった選択は「選択なし」など分かる表示へ戻せると、クラッシュを避けるだけでなく使う側も状況を理解できます。"],"id":"engine-safe-deletion-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"},{"title":"Cubos Team: Entity破棄イベントと参照の整理に関する開発記録","url":"https://cubos.riscadoa.com/blog/release-07/"}],"image":"guide-engine-workbench","image_scene":"example-engine-safe-deletion-02","image_caption":""},{"id":"engine-layout-settings","category":"engine","level":"intermediate","minutes":20,"title":"エディターの設定を保存する：レイアウトとプロジェクトデータを分ける","summary":"次に開いたときも同じ作業画面で始めたい。ウィンドウ配置、パネルの表示設定、シーンの保存を整理して、安心して再開できるようにします。","related_api":["ImGui::LoadIniSettingsFromMemory","ImGui::SaveIniSettingsToMemory","ImGui::GetIO","ImGui::Checkbox","ImGui::Begin"],"related_guides":["labels-hash","docking-layout","docking-config","engine-editor-architecture"],"tags":["設定保存","レイアウト","ini","プロジェクト"],"sections":[{"title":"「保存するもの」は、ひとつではない","paragraphs":["ImGuiのiniにはウィンドウ位置やサイズ、テーブル設定などのUI状態が保存されます。Dockingブランチならドッキング状態も対象です。**シーンの物体や材質、独自のチェック状態まで自動保存されるわけではありません。**","プロジェクト内容と個人の作業レイアウトは分けるのがおすすめです。他の人がシーンを開くたび自分のパネル配置まで上書きされると使いづらくなります。保存先と共有範囲を先に決めましょう。"],"table":{"headers":["保存するもの","保存先の例","保存する担当"],"rows":[["物体・材質・アセット参照","プロジェクトのシーンファイル","エンジンのシリアライザー"],["ウィンドウ・テーブル・Docking配置","ユーザーごとのlayout.ini","ImGuiのiniをアプリが管理"],["表示パネル・表示モード","ユーザー設定ファイル","アプリ独自の設定処理"]]},"id":"engine-layout-settings-section-1"},{"title":"iniを自分で管理したいときは、最初に切り替える","paragraphs":["通常はio.IniFilenameの既定値に従って自動保存されます。独自のプロジェクト設定に組み込むなら、コンテキスト作成後・最初のNewFrame()より前にIniFilenameをnullptrへ設定し、保存済みの文字列を読み込みます。","この関数は毎フレーム呼びません。作業中のレイアウトを毎フレーム読み戻すと、ユーザーが動かしたウィンドウまで元へ戻ってしまいます。"],"code":"#include \"imgui.h\"\n#include <string>\n    void ConfigureManualLayout(const std::string& saved_ini)\n    {\n        // CreateContext()の後、最初のNewFrame()より前に呼ぶ\n        ImGuiIO& io = ImGui::GetIO();\n        io.IniFilename = nullptr;\n        if (!saved_ini.empty())\n            ImGui::LoadIniSettingsFromMemory(\n                saved_ini.data(), saved_ini.size());\n    }","id":"engine-layout-settings-section-2","capture":{"guide_id":"engine-layout-settings","section_index":1,"scene":"example-engine-layout-settings-02","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"9d05646424d558febd804fa84a5522a91a692460c6b64a7429d7659bc4d7a50e","image_sha256":"70e68b62f21bf759a374649c5a96fa29938d6f45835e30bdfd2774627e92990c","fixture":"ConfigureManualLayout(\"\"); ImGui::TextUnformatted(\"ConfigureManualLayout was called with an empty saved layout.\"); ImGui::Text(\"Automatic ini file: %s\",ImGui::GetIO().IniFilename?ImGui::GetIO().IniFilename:\"disabled\"); ImGui::TextUnformatted(\"Application-managed ini storage is active.\");","initialization":""}},{"title":"保存したい合図が来たら、文字列を自分の保存先へ","paragraphs":["手動管理ではWantSaveIniSettingsを調べ、SaveIniSettingsToMemory()で得た文字列を保存します。戻り値のポインターを長期保持せず、必要ならアプリのstringへコピーしてください。","次は小さなデスクトップツール向けの同期書き込み例です。保存に失敗したらfalseを返し、要求フラグを残します。実製品では一時ファイルからの置き換えや非同期保存を検討し、エラー表示や再試行の間隔も用意しましょう。"],"code":"#include \"imgui.h\"\n#include <cstddef>\n#include <fstream>\n    bool SaveLayoutIfRequested(const char* path)\n    {\n        ImGuiIO& io = ImGui::GetIO();\n        if (!io.WantSaveIniSettings)\n            return true;\n        std::size_t length = 0;\n        const char* ini = ImGui::SaveIniSettingsToMemory(&length);\n        std::ofstream file(path, std::ios::binary | std::ios::trunc);\n        if (!file)\n            return false;\n        file.write(ini, static_cast<std::streamsize>(length));\n        file.close();\n        if (!file)\n            return false;\n        io.WantSaveIniSettings = false;\n        return true;\n    }","id":"engine-layout-settings-section-3","capture":{"guide_id":"engine-layout-settings","section_index":2,"scene":"example-engine-layout-settings-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"10003295c8d1fd291daa3554711e2e56932fdf3b60f0cd1c7aa8a40dd5efc8a6","image_sha256":"1c00345ec4b9af4c102164869d0c666938f4262994dca598673f78598bacacd6","fixture":"if(capture_frame==4)ImGui::GetIO().WantSaveIniSettings=true; const bool saved=SaveLayoutIfRequested(\"build/guide-example-layout.ini\"); std::ifstream file(\"build/guide-example-layout.ini\",std::ios::binary|std::ios::ate); ImGui::Text(\"SaveLayoutIfRequested: %s\",saved?\"true\":\"false\"); ImGui::Text(\"Saved bytes: %lld\",file?(long long)file.tellg():0LL); ImGui::Text(\"WantSaveIniSettings after saving: %s\",ImGui::GetIO().WantSaveIniSettings?\"true\":\"false\");","initialization":""}},{"title":"パネル名が変わると、レイアウトも別物になりやすい","paragraphs":["ImGuiの保存状態はウィンドウのIDと結び付いています。タイトルへ選択中ファイル名を入れるなら、例えばInspector: Cube###Inspectorのように固定IDを残すと、表示名が変わっても同じウィンドウとして扱えます。","アプリ独自のshow_inspectorやshow_content_browserは別途保存してください。古い設定を読むときの既定値や設定バージョンも用意すると、パネルを増やした後の更新が楽になります。"],"id":"engine-layout-settings-section-4"},{"title":"レイアウトを壊しても、戻せる入口を用意しよう","paragraphs":["メニューに「標準レイアウトへ戻す」を置くと、パネルを画面外へ動かしたときも復帰しやすくなります。Dockingの初期配置を適用する処理は、毎フレーム実行せず、初回や明示的なリセット時に限定します。","終了時だけ保存する設計では、強制終了時に設定が失われます。WantSaveIniSettingsへの対応、明示的な保存、終了時の未処理要求の確認を組み合わせ、どこまで復元するかを決めておきましょう。"],"id":"engine-layout-settings-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-layout-settings-02","image_caption":""},{"id":"engine-input-focus","category":"engine","level":"advanced","minutes":23,"title":"ショートカットとゲーム入力を整理する：いま操作している画面を優先しよう","summary":"Inspectorで名前を入力したらゲームも動いた。そんな二重入力を避けつつ、保存やScene操作のショートカットを使いやすくまとめます。","related_api":["ImGui::Shortcut","ImGui::SetNextItemShortcut","ImGui::IsWindowFocused","ImGui::GetIO","ImGui::IsItemHovered","ImGui::IsKeyDown"],"related_guides":["input-routing","engine-play-modes","engine-viewport-picking","engine-undo-redo"],"tags":["入力","ショートカット","フォーカス","ゲーム入力"],"sections":[{"title":"まずは「誰が使う入力か」を決める","paragraphs":["OSやバックエンドからの入力は、アプリの振り分けにかかわらずImGuiにも渡します。そのうえで外側のゲームへ渡すかをio.WantCaptureMouse / WantCaptureKeyboardで判断するのが基本です。入力をImGuiへ渡す段階で止めると、キーを離したことまで届かなくなります。","エディター内のSceneやGameパネルは、さらにアプリ独自の操作領域です。**外側のゲームへの入力振り分けと、ImGui内のパネル間のショートカットは分けて考える**と整理できます。WantTextInputは画面キーボードなどの要求で、入力キャプチャ全般の代わりにはなりません。"],"id":"engine-input-focus-section-1"},{"title":"パネルの操作は、Shortcutのルーティングを使う","paragraphs":["次の関数は有効なパネル内で毎フレーム呼びます。既定のShortcut()はフォーカス階層を考慮して、同じキーを使う項目どうしを調整します。生のIsKeyPressed()だけで全パネルが同じ操作を起動する構成を避けられます。","Ctrl+Sはアプリ全体の保存要求、Fはそのパネルで選択中の物体へ寄る要求です。要求を返すだけにし、保存やカメラ移動の実装は呼び出し元へ置きます。ルートの登録も必要なので、キーを押したフレームだけ関数を呼ぶ書き方にはしません。"],"code":"#include \"imgui.h\"\n    struct EditorShortcutRequests\n    {\n        bool save = false;\n        bool frame_selection = false;\n    };\n    EditorShortcutRequests DrawEditorShortcuts()\n    {\n        EditorShortcutRequests requests;\n        requests.save = ImGui::Shortcut(\n            ImGuiMod_Ctrl | ImGuiKey_S, ImGuiInputFlags_RouteGlobal);\n        requests.frame_selection = ImGui::Shortcut(ImGuiKey_F);\n        ImGui::SetNextItemShortcut(ImGuiMod_Ctrl | ImGuiKey_S);\n        requests.save |= ImGui::Button(\"Save\");\n        return requests;\n    }","id":"engine-input-focus-section-2","capture":{"guide_id":"engine-input-focus","section_index":1,"scene":"example-engine-input-focus-02","mode":"direct","caption":"掲載コードを実行した表示です。","backend":"DirectX 11 / WARP","code_sha256":"d1a7c467c3f5a10cc6b3f17405ed88de8a70ad3c63f4b3a38a1168d98cbe9dec","image_sha256":"529d34b1884ea352519c29f210b461660245741a5204f0cdc2d42f8e455bf405","fixture":"auto value=DrawEditorShortcuts(); ImGui::Text(\"Save request: %s / Frame selection: %s\",value.save?\"yes\":\"no\",value.frame_selection?\"yes\":\"no\");","initialization":""}},{"title":"外側のゲームへ渡すかを、小さな判定にまとめる","paragraphs":["次はImGui外のゲーム領域向けの基本ゲートです。ゲームの実行状態と、アプリが保持するゲーム領域の操作権に加え、ImGuiが使いたい入力を除外します。ImGuiのNewFrame()前に直前のキャプチャ出力を使ってイベントを振り分ける一般的なループもあるため、実際のバックエンド構成に合わせて読むタイミングを決めてください。","ゲーム側の押下状態を自前で保持する場合は、UIへ切り替わった際に押しっぱなしが残らない設計も必要です。キーアップを処理する方法や、フォーカスを失ったら状態をリセットする方法を用意します。"],"code":"#include \"imgui.h\"\n    struct GameInputPermission\n    {\n        bool mouse;\n        bool keyboard;\n    };\n    GameInputPermission GetExternalGameInputPermission(\n        bool playing, bool owns_game_input)\n    {\n        const ImGuiIO& io = ImGui::GetIO();\n        const bool enabled = playing && owns_game_input;\n        return {enabled && !io.WantCaptureMouse,\n            enabled && !io.WantCaptureKeyboard};\n    }","id":"engine-input-focus-section-3","capture":{"guide_id":"engine-input-focus","section_index":2,"scene":"example-engine-input-focus-03","mode":"result","caption":"掲載関数をサンプル引数で呼び、結果を確認する表示を撮影用に添えています。","backend":"DirectX 11 / WARP","code_sha256":"1b0ddd58b6285bee3cf0ca0684334c937b22d09e350e17909e1f9f0e6489704a","image_sha256":"e51f2425d8e5fe01034b052bbb70a3d3d5f39c7d80dfb62edf81f84250f1a52b","fixture":"auto value=GetExternalGameInputPermission(true,true); ImGui::TextUnformatted(\"Input: playing=true / owns_game_input=true\"); ImGui::Separator(); ImGui::Text(\"Game mouse allowed: %s\",value.mouse?\"yes\":\"no\"); ImGui::Text(\"Game keyboard allowed: %s\",value.keyboard?\"yes\":\"no\");","initialization":""}},{"title":"ImGui内のGameビューは、明示的な操作モードにする","paragraphs":["上のゲートは外側のゲーム領域向けです。ImGuiのウィンドウ内にImageでGameビューを置くと、そのウィンドウ自体が入力をキャプチャするため、そのままではゲーム操作が許可されない場合があります。そこでアプリ側で「Gameビューへ入力を渡す」という明示的なモードを持たせます。","例えばクリックでゲーム操作へ入り、Escで解除し、Inspectorを選んだら解除する、と決めます。キーボード・マウスの独占、カーソルロック、解除キーを一緒に設計し、テキスト欄やモーダルが開いているときは操作へ入らないようにします。単にWantCaptureMouseを常に無視する方法では、UIのクリックまでゲームへ流れます。"],"id":"engine-input-focus-section-4"},{"title":"入力を奪いすぎるフラグに気をつける","paragraphs":["RouteGlobalは、フォーカス中の項目やウィンドウが同じショートカットを登録していると、そちらを尊重する方針です。RouteOverActiveなどで無理に優先すると、InputTextが使うCtrl+AやCtrl+Zをエディター全体の操作が奪ってしまう場合があります。","**文字列編集中のDeleteでEntityを削除しない**ことを確認しましょう。保存、Undo、選択解除、カメラ操作、ゲーム入力の順に「テキスト編集中」「モーダル表示中」「Scene上」「Game操作中」の条件を表にして試すと、二重実行を見つけやすくなります。"],"id":"engine-input-focus-section-5"}],"sources":[{"title":"Dear ImGui v1.93.0: 公開APIと各関数の契約","url":"https://github.com/ocornut/imgui/blob/v1.93.0/imgui.h"},{"title":"公式FAQ: ID・入力・アプリとの役割分担","url":"https://github.com/ocornut/imgui/blob/v1.93.0/docs/FAQ.md"}],"image":"guide-engine-workbench","image_scene":"example-engine-input-focus-02","image_caption":""}]);
